import heapq
from collections import defaultdict

def sliding_window_median(nums, k):
    small, large = [], []
    small_size, large_size = 0, 0
    delayed = defaultdict(int)

    def prune(heap):
        while heap and delayed[heap[0] if heap is large else -heap[0]] > 0:
            val = heap[0] if heap is large else -heap[0]
            delayed[val] -= 1
            if delayed[val] == 0:
                del delayed[val]
            heapq.heappop(heap)

    def median():
        if k % 2 == 1:
            return float(small[0] * -1) if small_size > large_size else float(large[0])
        return (-small[0] + large[0]) / 2.0

    def rebalance():
        nonlocal small_size, large_size
        if small_size > large_size + 1:
            heapq.heappush(large, -heapq.heappop(small))
            small_size -= 1
            large_size += 1
            prune(small)
        elif small_size < large_size:
            heapq.heappush(small, -heapq.heappop(large))
            large_size -= 1
            small_size += 1
            prune(large)

    def add(num):
        nonlocal small_size, large_size
        if not small or num <= -small[0]:
            heapq.heappush(small, -num)
            small_size += 1
        else:
            heapq.heappush(large, num)
            large_size += 1
        rebalance()

    def remove(num):
        nonlocal small_size, large_size
        delayed[num] += 1
        if num <= -small[0]:
            small_size -= 1
            if num == -small[0]:
                prune(small)
        else:
            large_size -= 1
            if large and num == large[0]:
                prune(large)
        rebalance()

    result = []
    for i, num in enumerate(nums):
        add(num)
        if i >= k:
            remove(nums[i - k])
        if i >= k - 1:
            result.append(median())

    return result

